def inicializar_stock_disponible(apps, schema_editor):
    IngresoInventario = apps.get_model("farmacia", "IngresoInventario")
    Merma = apps.get_model("farmacia", "Merma")

    mermas_por_ingreso = {
        fila["ingreso_id"]: fila["total"]
        for fila in Merma.objects.values("ingreso_id").annotate(total=models.Sum("cantidad"))
    }
    lotes_actualizados = []
    for ingreso in IngresoInventario.objects.all().iterator(chunk_size=500):
        ingreso.stock_disponible = max(
            0,
            ingreso.cantidad - mermas_por_ingreso.get(ingreso.pk, 0),
        )
        lotes_actualizados.append(ingreso)
        if len(lotes_actualizados) == 500:
            IngresoInventario.objects.bulk_update(
                lotes_actualizados,
                ("stock_disponible",),
            )
            lotes_actualizados.clear()
    if lotes_actualizados:
        IngresoInventario.objects.bulk_update(
            lotes_actualizados,
            ("stock_disponible",),
        )


